import java.util.ArrayList;import java.util.Iterator;// CartItem.javaclass CartItem {    // Attributes    String itemName;    double price;    int quantity;    // Constructor    CartItem(String itemName, double price, int quantity) {        this.itemName = itemName;        this.price = price;        this.quantity = quantity;    }    // Method to calculate total price for this item    double getTotalPrice() {        return price * quantity;    }    // Display item details    void displayItem() {        System.out.println(itemName + " - Price: $" + price + ", Quantity: " + quantity + ", Total: $" + getTotalPrice());    }}// ShoppingCart class to manage multiple itemsclass ShoppingCart {    ArrayList<CartItem> cart;    ShoppingCart() {        cart = new ArrayList<>();    }    // Add item to cart    void addItem(String itemName, double price, int quantity) {        CartItem newItem = new CartItem(itemName, price, quantity);        cart.add(newItem);        System.out.println(itemName + " added to cart.");    }    // Remove item from cart    void removeItem(String itemName) {        Iterator<CartItem> iterator = cart.iterator();        boolean found = false;        while (iterator.hasNext()) {            CartItem item = iterator.next();            if (item.itemName.equalsIgnoreCase(itemName)) {                iterator.remove();                System.out.println(itemName + " removed from cart.");                found = true;                break;            }        }        if (!found) {            System.out.println(itemName + " not found in cart.");        }    }    // Display total cost    void displayTotalCost() {        double total = 0;        System.out.println("\nItems in Cart:");        for (CartItem item : cart) {            item.displayItem();            total += item.getTotalPrice();        }        System.out.println("Total Cost: $" + total);    }}// Main class to test the ShoppingCartpublic class ShoppingCartTest {    public static void main(String[] args) {        ShoppingCart cart = new ShoppingCart();        cart.addItem("Laptop", 750.00, 1);        cart.addItem("Mouse", 25.00, 2);        cart.addItem("Keyboard", 45.00, 1);        cart.displayTotalCost();        cart.removeItem("Mouse");        cart.displayTotalCost();    }}